/// `tests/bugs/moddata_3/bug31587_3`
/// kentron: sub-shapes named by OCCT's enumeration are selected by position (draw_selectors.json)
#[test]
#[should_panic]
fn bug31587_3() {
    expected_failure(|| {
        let mut d = Draw::new();
        d.r#box(&["b", "10", "10", "10"])?;
        d.r#box(&["b1", "2", "2", "-1", "3", "2", "2"])?;
        d.explode(&["b1", "f"])?;
        d.nearest(&["b1_1", "b1", "F", "2.0", "3.0", "2.42861e-17", "4.0"])?;
        d.nearest(&["b1_2", "b1", "F", "5.0", "3.0", "2.42861e-17", "4.0"])?;
        d.bclearobjects(&[])?;
        d.bcleartools(&[])?;
        d.baddobjects(&["b"])?;
        d.baddtools(&["b1_1", "b1_2"])?;
        d.bfillds(&[])?;
        d.bsplit(&["r"])?;
        d.removeinternals(&["r"])?;
        d.checkshape(&["r"])?;
        d.checknbshapes(&["r", "-vertex", "8", "-edge", "12", "-wire", "6", "-face", "6", "-shell", "1", "-solid", "1"])?;
        d.bbuild(&["r"])?;
        d.bbuild(&["r1"])?;
        d.removeinternals(&["r1", "0"])?;
        d.checkshape(&["r1"])?;
        let t1 = d.nbshapes(&["r"])?;
        d.checknbshapes(&["r1", "-ref", t1.as_str()])?;
        d.removeinternals(&["r1", "1"])?;
        d.checkshape(&["r1"])?;
        d.checknbshapes(&["r1", "-vertex", "20", "-edge", "26", "-wire", "10", "-face", "10", "-shell", "1", "-solid", "1"])?;
        d.explode(&["r1", "so"])?;
        d.nearest(&["r1_1", "r1", "SO", "5.0", "5.0", "5.0", "1000.0"])?;
        d.checknbshapes(&["r1_1", "-vertex", "8", "-edge", "12", "-wire", "6", "-face", "6", "-shell", "1", "-solid", "1"])?;
        Ok(())
    })
}

